import struct
p='/out-vul/cli-uart-received-fuzzer'
b=open(p,'rb').read()
base=0x400000
for off in range(0, len(b)-24, 8):
    s, fn, adj = struct.unpack_from('<QQQ', b, off)
    if not (0x490000 <= s < 0x4a09d4 and 0x4014d0 <= fn < 0x4900c4 and adj == 0):
        continue
    so=s-base
    if not (0 <= so < len(b)): continue
    end=b.find(b'\0',so,min(so+80,len(b)))
    if end<0: continue
    raw=b[so:end]
    if not raw or any(c<0x20 or c>=0x7f for c in raw): continue
    try: name=raw.decode()
    except: continue
    if len(name)<=40:
        print(f'{base+off:08x} {fn:08x} {name}')
PY"}

